input.find:
_collectValue(value, previous) {
  if (previous !== this.defaultValue || !Array.isArray(previous)) {
    return [value];
  }

  previous.push(value);
  return previous;
}

input.replace:
_collectValue(value, previous) {
  if (!Array.isArray(previous)) {
    return [value];
  }

  previous.push(value);
  return previous;
}
